//! Culture-specific letter order of the linguistic collation ([`super::collation`]).
//!
//! Observed on the engine of Power BI Desktop 2.158: a model of each culture sorted the same
//! probe words (`crates/locale/tests/oracle/expected.json`, `sort`; corpus generated by
//! `tools/locale-oracle/gen_cases.mjs`). Only the letters the probes cover are tailored; other
//! letters keep the default order.

use super::collation::{LATIN_STEP, latin_primary};

/// Tertiary weight of a contraction (`aa` after `å` in Danish).
const T_CONTRACTION: u8 = 4;

/// Culture-specific letter order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Tailoring {
    None,
    /// es: ñ after n.
    Spanish,
    /// sv, fi: å ä ö after z, ü with y, w with v.
    Swedish,
    /// da: æ ø å after z, `aa` as å, ü with y.
    Danish,
    /// nb, nn: æ ø å after z, ü with y.
    Norwegian,
    /// pl: ą ć ę ł ń ó ś ź ż after their base letters.
    Polish,
    /// cs: č, ch (after h), ř, š, ž.
    Czech,
    /// sk: as Czech, plus ä after a.
    Slovak,
    /// tr, az: ç ğ ı ö ş ü; `I` lowercases to `ı`, `İ` to `i`.
    Turkish,
    /// ro: ă â î ș ț.
    Romanian,
    /// hu: cs dz dzs gy ly ny sz ty zs, ö ő after o, ü ű after u.
    Hungarian,
    /// lt: ą č ę š ž, y right after i.
    Lithuanian,
    /// lv: č š ž.
    Latvian,
    /// et: š z ž after s, w with v, õ ä ö ü after v.
    Estonian,
    /// hr, bs, sr-Latn: č ć dž đ lj nj š ž.
    Croatian,
    /// sl: č ć š ś ž ź.
    Slovenian,
    /// is: á ð é í ó ú ý after their letters, þ æ ö after z.
    Icelandic,
}

/// One tailored letter or contraction (lowercase): `rank` steps after the base letter (0: with
/// it), with an accent weight.
struct Rule {
    text: &'static str,
    base: char,
    rank: u32,
    secondary: u16,
}

const fn r(text: &'static str, base: char, rank: u32, secondary: u16) -> Rule {
    Rule {
        text,
        base,
        rank,
        secondary,
    }
}

const SPANISH: &[Rule] = &[r("ñ", 'n', 2, 0)];
const SWEDISH: &[Rule] = &[
    r("å", 'z', 1, 0),
    r("ä", 'z', 2, 0),
    r("ö", 'z', 3, 0),
    r("ő", 'z', 3, 1),
    r("ø", 'z', 3, 2),
    r("ű", 'y', 0, 1),
    r("ü", 'y', 0, 2),
    r("w", 'v', 0, 1),
];
const DANISH: &[Rule] = &[
    r("æ", 'z', 1, 0),
    r("ä", 'z', 1, 1),
    r("ø", 'z', 2, 0),
    r("ö", 'z', 2, 1),
    r("ő", 'z', 2, 2),
    r("å", 'z', 3, 0),
    r("aa", 'z', 3, 0),
    r("ű", 'y', 0, 1),
    r("ü", 'y', 0, 2),
];
const NORWEGIAN: &[Rule] = &[
    r("æ", 'z', 1, 0),
    r("ä", 'z', 1, 1),
    r("ø", 'z', 2, 0),
    r("ö", 'z', 2, 1),
    r("ő", 'z', 2, 2),
    r("å", 'z', 3, 0),
    r("ű", 'y', 0, 1),
    r("ü", 'y', 0, 2),
];
const POLISH: &[Rule] = &[
    r("ą", 'a', 1, 0),
    r("ć", 'c', 1, 0),
    r("ę", 'e', 1, 0),
    r("ł", 'l', 1, 0),
    r("ń", 'n', 1, 0),
    r("ó", 'o', 1, 0),
    r("ś", 's', 1, 0),
    r("ź", 'z', 1, 0),
    r("ż", 'z', 2, 0),
];
const CZECH: &[Rule] = &[
    r("č", 'c', 1, 0),
    r("ch", 'h', 1, 0),
    r("ř", 'r', 1, 0),
    r("š", 's', 1, 0),
    r("ž", 'z', 1, 0),
];
const SLOVAK: &[Rule] = &[
    r("ä", 'a', 1, 0),
    r("č", 'c', 1, 0),
    r("ch", 'h', 1, 0),
    r("ř", 'r', 1, 0),
    r("š", 's', 1, 0),
    r("ž", 'z', 1, 0),
];
const TURKISH: &[Rule] = &[
    r("ç", 'c', 1, 0),
    r("ğ", 'g', 1, 0),
    r("ı", 'h', LATIN_STEP - 1, 0),
    r("ö", 'o', 1, 0),
    r("ş", 's', 1, 0),
    r("ü", 'u', 1, 0),
];
const ROMANIAN: &[Rule] = &[
    r("ă", 'a', 1, 0),
    r("â", 'a', 2, 0),
    r("î", 'i', 1, 0),
    r("ș", 's', 1, 0),
    r("ş", 's', 1, 0),
    r("ț", 't', 1, 0),
    r("ţ", 't', 1, 0),
];
